// running() FX.cpp:546: alternating pixels running
function running(S, E, color1, color2, theatre) {
	const width = (theatre ? 3 : 1) + (S.intensity >> 4); // window
	const cycleTime = 50 + (255 - S.speed);
	const it = Math.floor(S.now / cycleTime);
	const usePalette = color1 == S.col[0];
	for (let i = 0; i < S.len; i++) {
		let col = color2;
		if (usePalette) color1 = S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 0);
		if (theatre) {
			if ((i % width) == E.aux0) col = color1;
		} else {
			const pos = i % (width << 1);
			if ((pos < E.aux0 - width) || ((pos >= E.aux0) && (pos < E.aux0 + width))) col = color1;
		}
		S.setPixelColor(i, col);
	}
	if (it != E.step) {
		E.aux0 = (E.aux0 + 1) % (theatre ? width : (width << 1));
		E.step = it;
	}
}
