// running_base() FX.cpp:594: running lights with smooth sine or sawtooth transition
function running_base(S, saw, dual) {
	const len = S.len;
	const x_scale = S.intensity >> 2;
	const counter = Math.imul(S.now, S.speed) >>> 9;
	for (let i = 0; i < len; i++) {
		let a = (i * x_scale - counter) >>> 0;
		if (saw) {
			a &= 0xFF;
			if (a < 16) a = 192 + a * 8;
			else a = map(a, 16, 255, 64, 192);
			a = 255 - a; // may go negative: sin8_t below takes it as uint8
		}
		const s = dual ? sin_gap(a) : sin8_t(a & 0xFF);
		let ca = color_blend(S.col[1], S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 0), s);
		if (dual) {
			const b = ((len - 1 - i) * x_scale - counter) >>> 0;
			const t = sin_gap(b);
			const cb = color_blend(S.col[1], S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 2), t);
			ca = color_blend(ca, cb, 127);
		}
		S.setPixelColor(i, ca);
	}
}
FXS.add("Running Dual", S => running_base(S, false, true)); // mode_running_dual() FX.cpp:627
FXS.add("Running", S => running_base(S, false, false)); // mode_running_lights() FX.cpp:636
FXS.add("Saw", S => running_base(S, true, false)); // mode_saw() FX.cpp:645

// mode_twinkle() FX.cpp:655
FXS.add("Twinkle", function(S, E) {
	S.fade_out(224);
	const cycleTime = 20 + (255 - S.speed) * 5;
	const it = Math.floor(S.now / cycleTime);
	if (it != E.step) {
		const maxOn = map(S.intensity, 0, 255, 1, S.len); // make sure at least one LED is on
		if (E.aux0 >= maxOn) {
			E.aux0 = 0;
			E.aux1 = hw_random() & 0xFFFF; // new seed for our PRNG
		}
		E.aux0 = (E.aux0 + 1) & 0xFFFF;
		E.step = it;
	}
	let PRNG16 = E.aux1;
	for (let i = 0; i < E.aux0; i++) {
		PRNG16 = (((PRNG16 * 2053) & 0xFFFF) + 13849) & 0xFFFF; // next 'random' number
		const j = (S.len * PRNG16) >>> 16;
		S.setPixelColor(j, S.color_from_palette(j, true, S.PALETTE_SOLID_WRAP, 0));
	}
});

// dissolve() FX.cpp:688; the uint32 pixel array in SEGENV.data lives in E.s.px
function dissolve(S, E, color) {
	const len = S.len, c1 = S.col[1];
	let pixels = E.s.px;
	if (!pixels || pixels.length != len) pixels = E.s.px = new Uint32Array(len); // allocateData(): zeroed on (re)allocation
	if (E.call == 0) {
		pixels.fill(c1);
		E.aux0 = 1;
	}
	for (let j = 0; j <= Math.floor(len / 15); j++) {
		if (hw_random8() <= S.intensity) {
			for (let times = 0; times < 10; times++) { // attempt to spawn a new pixel 10 times
				const i = hw_random16(len);
				if (E.aux0) { // dissolve to primary/palette
					if (pixels[i] == c1) {
						let c = color == S.col[0] ? S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 0) : color;
						if (S.check2 && c == c1) c = (c ^ 1) >>> 0; // change the color slightly so Complete mode can't get stuck
						pixels[i] = c;
						break; // only spawn 1 new pixel per frame
					}
				} else if (pixels[i] != c1) { // dissolve to secondary
					pixels[i] = c1;
					break;
				}
			}
		}
	}
	let incompletePixels = 0;
	for (let i = 0; i < len; i++) {
		S.setPixelColor(i, pixels[i]);
		if (S.check2) {
			if (E.aux0) { if (pixels[i] == c1) incompletePixels++; }
			else if (pixels[i] != c1) incompletePixels++;
		}
	}
	if (E.step > (255 - S.speed) + 15) {
		E.aux0 = E.aux0 ? 0 : 1;
		E.step = 0;
	} else if (S.check2) {
		if (incompletePixels == 0) E.step++; // only advance step once all pixels have changed
	} else E.step++;
}
