// mode_drip() FX.cpp:3867 (1D: one virtual strip)
FXS.add("Drip", function(S, E) {
	if (S.len <= 1) return mode_static(S);
	const s = E.s, len = S.len;
	if (!s.drops) s.drops = Array.from({length: 4}, newSpark); // maxNumDrops = 4
	if (!S.check2) S.fill(S.col[1]);
	// virtualStrip::runStrip()
	const numDrops = 1 + (S.intensity >> 6); // 255>>6 = 3
	let gravity = -0.0005 - (S.speed / 50000.0);
	gravity *= Math.max(1, len - 1);
	const sourcedrop = 12;
	for (let j = 0; j < numDrops; j++) {
		const d = s.drops[j];
		if (d.colIndex == 0) { // init
			d.pos = len - 1; // start at end
			d.vel = 0;
			d.col = sourcedrop; // brightness
			d.colIndex = 1; // drop state (0 init, 1 forming, 2 falling, 5 bouncing)
		}
		S.setPixelColor(len - 1, color_blend(BLACK, S.col[0], sourcedrop)); // water source
		if (d.colIndex == 1) {
			if (d.col > 255) d.col = 255;
			S.setPixelColor(Math.trunc(d.pos) & 0xFFFF, color_blend(BLACK, S.col[0], d.col & 0xFF));
			d.col = (d.col + map(S.speed, 0, 255, 1, 6)) & 0xFFFF; // swelling
			if (hw_random8() < Math.trunc(d.col / 10)) { // random drop
				d.colIndex = 2; // fall
				d.col = 255;
			}
		}
		if (d.colIndex > 1) { // falling
			if (d.pos > 0) { // fall until end of segment
				d.pos += d.vel;
				if (d.pos < 0) d.pos = 0;
				d.vel += gravity; // gravity is negative
				for (let i = 1; i < 7 - d.colIndex; i++) { // some minor math so we don't expand bouncing droplets
					const pos = constrain((Math.trunc(d.pos) >>> 0) + i, 0, len - 1);
					S.setPixelColor(pos, color_blend(BLACK, S.col[0], Math.trunc(d.col / i) & 0xFF)); // spread pixel with fade while falling
				}
				if (d.colIndex > 2) S.setPixelColor(0, color_blend(S.col[0], BLACK, d.col & 0xFF)); // during bounce, some water is on the floor
			} else { // we hit bottom
				if (d.colIndex > 2) { // already hit once, so back to forming
					d.colIndex = 0;
					d.col = sourcedrop;
				} else {
					if (d.colIndex == 2) { // init bounce
						d.vel = -d.vel / 4; // reverse velocity with damping
						d.pos += d.vel;
					}
					d.col = sourcedrop * 2;
					d.colIndex = 5; // bouncing
				}
			}
		}
	}
});

// mode_tetrix() FX.cpp:3961 (Tetris struct FX.cpp:3952, 1D: one virtual strip)
FXS.add("Tetrix", function(S, E) {
	if (S.len <= 1) return mode_static(S);
	const s = E.s, len = S.len;
	if (!s.drop) s.drop = {pos: 0, speed: 0, col: 0, brick: 0, stack: 0, step: 0};
	const drop = s.drop;
	// virtualStrip::runStrip()
	if (E.call == 0) { // initialize dropping on first call or segment full
		drop.stack = 0; // reset brick stack size
		drop.step = (S.now + 2000) >>> 0; // start by fading out strip
		if (S.check1) drop.col = 0; // use only one color from palette
	}
	if (drop.step == 0) { // init brick
		let speed = S.speed ? S.speed : hw_random8(1, 255);
		speed = map(speed, 1, 255, 5000, 250); // time taken for full (SEGLEN) drop
		drop.speed = (len * S.frametime) / speed;
		drop.pos = len; // start at end of segment
		if (!S.check1) drop.col = (hw_random8(0, 15) << 4) & 0xFF; // limit color choices so there is enough HUE gap
		drop.step = 1; // drop state (0 init, 1 forming, 2 falling)
		drop.brick = ((S.intensity ? (S.intensity >> 5) + 1 : hw_random8(1, 5)) * (1 + (len >> 6))) & 0xFFFF; // size of brick
	}
	if (drop.step == 1) { // forming
		if (hw_random8() >> 6) drop.step = 2; // random drop
	}
	if (drop.step == 2) { // falling
		if (drop.pos > drop.stack) { // fall until top of stack
			drop.pos -= drop.speed;
			if (Math.trunc(drop.pos) < drop.stack) drop.pos = drop.stack;
			const p = Math.trunc(drop.pos) >>> 0;
			for (let i = p; i < len; i++) {
				const col = i < p + drop.brick ? S.color_from_palette(drop.col, false, false, 0) : S.col[1];
				S.setPixelColor(i, col);
			}
		} else { // we hit bottom
			drop.step = 0; // proceed with next brick, go back to init
			drop.stack = (drop.stack + drop.brick) & 0xFFFF; // increase the stack size
			if (drop.stack >= len) drop.step = (S.now + 2000) >>> 0; // fade out stack
		}
	}
	if (drop.step > 2) { // fade strip
		drop.brick = 0; // reset brick size (no more growing)
		if (drop.step > S.now) {
			for (let i = 0; i < len; i++) S.blendPixelColor(i, S.col[1], 25); // 10% blend
		} else {
			drop.stack = 0; // reset brick stack size
			drop.step = 0; // proceed with next brick
			if (S.check1) drop.col = (drop.col + 8) & 0xFF; // gradually increase palette index
		}
	}
});

// mode_plasma() FX.cpp:4040
FXS.add("Plasma", function(S, E) {
	if (E.call == 0) E.aux0 = hw_random8(0, 2); // add a bit of randomness
	const thisPhase = beatsin8_t(6 + E.aux0, 192, 64); // lowest -64 passed as uint8_t = 192
	const thatPhase = beatsin8_t(7 + E.aux0, 192, 64);
	const f1 = 2 + 3 * (S.speed >> 5), f2 = 1 + 2 * (S.speed >> 5);
	const cut = beatsin8_t(7, 0, 128 - (S.intensity >> 1)); // hoisted: depends on time only
	for (let i = 0; i < S.len; i++) {
		const colorIndex = (cubicwave8((i * f1 + thisPhase) & 0xFF) >> 1) + (cos8_t((i * f2 + thatPhase) & 0xFF) >> 1);
		const thisBright = qsub8(colorIndex, cut);
		S.setPixelColor(i, S.color_from_palette(colorIndex, false, PSW, 0, thisBright));
	}
});

// mode_percent() FX.cpp:4062
FXS.add("Percent", function(S, E) {
	const len = S.len;
	const percent = constrain(S.intensity, 0, 200);
	const active_leds = (percent < 100) ? Math.round(len * percent / 100.0) : Math.round(len * (200 - percent) / 100.0);
	let size = 1 + ((S.speed * len) >> 11);
	if (S.speed == 255) size = 255;
	if (percent <= 100) {
		for (let i = 0; i < len; i++) {
			if (i < E.aux1) {
				if (S.check1) S.setPixelColor(i, S.color_from_palette(map(percent, 0, 100, 0, 255), false, false, 0));
				else S.setPixelColor(i, S.color_from_palette(i, true, PSW, 0));
			} else S.setPixelColor(i, S.col[1]);
		}
	} else {
		for (let i = 0; i < len; i++) {
			if (i < (len - E.aux1)) S.setPixelColor(i, S.col[1]);
			else if (S.check1) S.setPixelColor(i, S.color_from_palette(map(percent, 100, 200, 255, 0), false, false, 0));
			else S.setPixelColor(i, S.color_from_palette(i, true, PSW, 0));
		}
	}
	if (active_leds > E.aux1) { // smooth transition to the target value
		E.aux1 = (E.aux1 + size) & 0xFFFF;
		if (E.aux1 > active_leds) E.aux1 = active_leds;
	} else if (active_leds < E.aux1) {
		if (E.aux1 > size) E.aux1 -= size; else E.aux1 = 0;
		if (E.aux1 < active_leds) E.aux1 = active_leds;
	}
});

// mode_heartbeat() FX.cpp:4113
FXS.add("Heartbeat", function(S, E) {
	const bpm = 40 + (S.speed >> 3);
	const msPerBeat = Math.trunc(60000 / bpm);
	const secondBeat = Math.trunc(msPerBeat / 3);
	let bri_lower = E.aux1;
	const beatTimer = (S.now - E.step) >>> 0;
	bri_lower = Math.trunc(bri_lower * 2042 / (2048 + S.intensity));
	E.aux1 = bri_lower;
	if ((beatTimer > secondBeat) && !E.aux0) { // time for the second beat?
		E.aux1 = 0xFFFF; // 3/4 bri
		E.aux0 = 1;
	}
	if (beatTimer > msPerBeat) { // time to reset the beat timer?
		E.aux1 = 0xFFFF; // full bri
		E.aux0 = 0;
		E.step = S.now;
	}
	const bl = 255 - (E.aux1 >> 8);
	for (let i = 0; i < S.len; i++) S.setPixelColor(i, color_blend(S.color_from_palette(i, true, PSW, 0), S.col[1], bl));
});

