// pacifica_one_layer() FX.cpp:4165: one layer of waves; cistart, wavescale, ioff are uint16_t, bri uint8_t
function pacifica_one_layer(S, i, p, cistart, wavescale, bri, ioff) {
	let ci = cistart & 0xFFFF;
	let waveangle = ioff & 0xFFFF;
	const wavescale_half = ((wavescale & 0xFFFF) >> 1) + 20;
	waveangle += (120 + S.intensity) * i; // original 250 * i
	const s16 = sin16_t(waveangle & 0xFFFF) + 32768;
	const cs = scale16(s16, wavescale_half) + wavescale_half;
	ci = (ci + cs * i) >>> 0;
	const sindex16 = sin16_t(ci & 0xFFFF) + 32768;
	const sindex8 = scale16(sindex16, 240);
	return ColorFromPalette(p, sindex8, bri, LINEARBLEND);
}

