	const hueOffset0 = (volX0 + hueX0) & 0xFF; // derive a 3rd random number
	const cozy = S.check3; // soft wraparound of the color palette
	const volSpeed = 1 + S.speed, hueSpeed = 1 + S.intensity, volSqueeze = 8 + S.custom1, hueSqueeze = S.custom2;
