		vol = map(vol, volCutoff, volSaturate, 0, 255);
		vol = constrain(vol, 0, 255);
		const hueX = (i * hueSqueeze * 8) >>> 0;
		let hue = (perlin16((hueX0 + hueX) >>> 0, hueT) >> 7) & 0xFF;
		hue = (hue + hueOffset0) & 0xFF;
		hue = (hue + hueOffset) & 0xFF;
